// Contract between the game and the portal adapters. Only the director changes it.

export type PlatformName = 'local' | 'poki' | 'crazygames'

export type RunMode = 'city' | 'daily'

export type LifelineKind = 'fiftyFifty' | 'extraTime' | 'skipVideo'

export type RewardedAdOutcome = 'completed' | 'cancelled' | 'unavailable'

export interface RewardedAdResult {
  attemptId: string
  outcome: RewardedAdOutcome
}

export interface RewardedAdRequest {
  /** Generated by the game for each attempt. Results are matched to it. */
  attemptId: string
  /** The spot actually started playing. The game mutes its audio. */
  onStart(): void
  /**
   * The SDK finished the attempt. Portals may call this late or more than once.
   * The adapter forwards what it receives and the game accepts only the first result
   * of the attempt that is currently running.
   */
  onResult(result: RewardedAdResult): void
}

/** Aggregated events without player identifiers (brief §13). */
export type AnalyticsEvent =
  | { name: 'route_started'; cityId: string; mode: RunMode; resumed: boolean }
  | {
      name: 'question_resolved'
      cityId: string
      /** Stop number within the run, 1–10 for a city route and 1–3 for the daily challenge. */
      index: number
      mode: RunMode
      outcome: 'correct' | 'wrong' | 'timeout' | 'skipped'
    }
  | { name: 'route_completed'; cityId: string; mode: RunMode; correct: number; stars: number }
  | {
      name: 'route_left'
      cityId: string
      mode: RunMode
      /** Stop number within the run, 1-based like `question_resolved.index`. */
      index: number
      reason: 'abandoned' | 'paused'
    }
  | { name: 'lifeline_used'; lifeline: LifelineKind; mode: RunMode }
  | { name: 'rewarded_ad_outcome'; outcome: RewardedAdOutcome }
  | { name: 'daily_completed'; utcDate: string; correct: number }
  | { name: 'postcard_unlocked'; cityId: string }

/**
 * Raw key-value persistence (localStorage or a portal data module).
 * Both methods throw when the storage is unavailable; `src/game/storage` falls back to memory.
 */
export interface KeyValueStore {
  read(key: string): string | null
  write(key: string, value: string): void
}

export interface PlatformAdapter {
  readonly name: PlatformName
  readonly store: KeyValueStore
  /**
   * Loads and initialises the SDK. Resolves even when the SDK is blocked or does not answer within
   * the adapter's time limit (5 s); the game then runs without ads.
   */
  init(): Promise<void>
  loadingStarted(): void
  loadingFinished(): void
  /** Repeated calls without `gameplayStop` in between are merged into one signal. */
  gameplayStart(): void
  /** Repeated calls without `gameplayStart` in between are merged into one signal. */
  gameplayStop(): void
  /** Known up front, e.g. false on CrazyGames Basic Launch or without an SDK. The skip lifeline is hidden when false. */
  rewardedAdsOffered(): boolean
  /**
   * The adapter stops the gameplay signal before the spot and keeps it stopped.
   * The game calls `gameplayStart` again when the player is back in an active question.
   */
  requestRewardedAd(request: RewardedAdRequest): void
  track(event: AnalyticsEvent): void
  /** Events tracked in this session. Recorded by every adapter in development builds, empty in production builds. */
  recordedEvents(): readonly AnalyticsEvent[]
  /**
   * The portal asks the game to mute its audio (CrazyGames `game.settings.muteAudio`), with priority over
   * the game's own sound setting. Valid after `init()` resolves. False without an SDK, after a failed or
   * timed-out `init()` and on every platform other than CrazyGames. Vibration is not affected.
   */
  portalAudioMuted(): boolean
  /** Called only when `portalAudioMuted()` actually changes. Never called where the portal reports no changes. */
  onPortalAudioMutedChange(listener: (muted: boolean) => void): void
}
